#pragma once
#include "kstationNativeArpMain.h"
#include "kstationNativeMidiEvent.h"
#include <array>
#include <type_traits>
#include <variant>
namespace kstation {
class NativeArp final {
 using M=NativeArpMain;using G=NativeArpGate;using C=NativeMidiClearNotes;using H=NativeMidiPhysicalScan;using S=NativeArpStep;using D=NativeArpRandom;using Q=NativeArpMidiEnqueue;using O=NativeArpMidiOutput;using E=NativeArpEmit;using L=NativeArpLed;using P=NativeArpSchedule;using A=NativeArpPitchOrder;using K=NativeArpSeekEmit;using F=NativeMidiSeekNote;using Job=std::variant<std::monostate,M,G,C,H,S,D,Q,O,E,L,P,A,K,F>;
public:
 enum class External:uint8_t { None,ReleaseVoices,Step,SendOutput,Release,RandomIndex,OtherMode,Emit,Tick,Schedule,StartVoice };
 struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,8>CodeRanges{{{0xb0c,0xb50},{0x20ce,0x20e2},{0x255a,0x2590},{0x2b7a,0x2baa},{0x2c16,0x2c36},{0x2c86,0x2ce8},{0x3446,0x359c},{0x359c,0x3812}}};
 static bool candidate(uint32_t pc){for(auto r:CodeRanges)if(pc>=r.begin&&pc<r.end)return true;return false;}
 void reset(){for(auto&j:jobs_)j.emplace<std::monostate>();depth_=0;}bool active()const{return depth_!=0;}
 External external()const{if(!depth_)return External::None;const auto&j=jobs_[depth_-1];if(auto*p=std::get_if<M>(&j);p&&p->task().awaitingChild()){if(p->task().child()==ArpMainTask::Child::ReleaseVoices)return External::ReleaseVoices;}if(auto*p=std::get_if<G>(&j);p&&p->task().awaitingChild()){if(p->task().child()==ArpGateTask::Child::Release)return External::Release;}if(auto*p=std::get_if<S>(&j);p&&p->task().awaitingChild()){switch(p->task().child()){case ArpStepTask::Child::RandomIndex:break;case ArpStepTask::Child::OtherMode:break;case ArpStepTask::Child::Emit:break;}}if(auto*p=std::get_if<D>(&j);p&&p->task().awaitingTick())return External::Tick;if(auto*p=std::get_if<E>(&j);p&&p->task().awaitingChild()){if(p->task().child()==ArpEmitTask::Child::StartVoice)return External::StartVoice;}return External::None;}
 bool step(Stage1Cpu&c){if(midi_projection::blocked(c))return false;for(unsigned n=0;n<jobs_.size()+1;++n){if(!depth_&&!push(c,false))return false;auto&j=jobs_[depth_-1];if(awaiting(j)){if(resume(j,c)){if(complete(j)){j.emplace<std::monostate>();--depth_;}continue;}if(uint32_t(c.getPC())!=childEntry(j)||!push(c,true))return false;continue;}const bool ok=std::visit([&](auto&v)->bool{using V=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<V,std::monostate>)return false;else return v.step(c);},j);if(!ok)return false;if(complete(j)){j.emplace<std::monostate>();--depth_;}return true;}return false;}
private:
 static bool awaiting(const Job&j){return std::visit([](const auto&v)->bool{using V=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<V,M>||std::is_same_v<V,G>||std::is_same_v<V,S>||std::is_same_v<V,O>||std::is_same_v<V,E>||std::is_same_v<V,P>||std::is_same_v<V,A>||std::is_same_v<V,K>)return v.task().awaitingChild();else if constexpr(std::is_same_v<V,D>)return v.task().awaitingTick();else return false;},j);}
 static bool complete(const Job&j){return std::visit([](const auto&v)->bool{using V=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<V,std::monostate>)return true;else return v.task().complete();},j);}
 static bool resume(Job&j,Stage1Cpu&c){return std::visit([&](auto&v)->bool{using V=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<V,M>||std::is_same_v<V,G>||std::is_same_v<V,S>||std::is_same_v<V,D>||std::is_same_v<V,O>||std::is_same_v<V,E>||std::is_same_v<V,P>||std::is_same_v<V,A>||std::is_same_v<V,K>)return v.resumeChild(c);else return false;},j);}
 static uint32_t childEntry(const Job&j){if(auto*p=std::get_if<M>(&j)){switch(p->task().child()){case ArpMainTask::Child::ClearHeld:return 0x2b7a;case ArpMainTask::Child::ReleaseVoices:return 0x7644;case ArpMainTask::Child::Gate:return 0x359c;case ArpMainTask::Child::Step:return 0x35fe;}}if(auto*p=std::get_if<G>(&j)){switch(p->task().child()){case ArpGateTask::Child::HeldScan:return 0x2c16;case ArpGateTask::Child::SendOutput:return 0x255a;case ArpGateTask::Child::Release:return 0x759a;}}if(auto*p=std::get_if<S>(&j)){switch(p->task().child()){case ArpStepTask::Child::RandomIndex:return 0x3660;case ArpStepTask::Child::OtherMode:return 0x368a;case ArpStepTask::Child::Emit:return 0x37ce;}}if(std::holds_alternative<D>(j))return 0x9aa;if(std::holds_alternative<O>(j))return 0xb0c;if(auto*p=std::get_if<E>(&j)){switch(p->task().child()){case ArpEmitTask::Child::Schedule:return 0x354e;case ArpEmitTask::Child::SendOutput:return 0x2570;case ArpEmitTask::Child::StartVoice:return 0x33f4;case ArpEmitTask::Child::Led:return 0x20ce;}}if(std::holds_alternative<P>(j))return 0x35bc;if(auto*p=std::get_if<A>(&j)){switch(p->task().child()){case ArpPitchOrderTask::Child::HeldScan:return 0x2c16;case ArpPitchOrderTask::Child::SeekUp:return 0x37ac;case ArpPitchOrderTask::Child::SeekDown:return 0x37b6;case ArpPitchOrderTask::Child::EmitValue:return 0x37c0;}}if(auto*p=std::get_if<K>(&j))return p->task().child()==ArpSeekEmitTask::Child::Seek?(p->task().kind()==ArpSeekEmitTask::Kind::Up?0x2c86:0x2cb8):0x37ce;return 0;}
 bool push(Stage1Cpu&c,bool nested){if(depth_==jobs_.size())return false;auto&j=jobs_[depth_];switch(uint32_t(c.getPC())){case 0x3446:j.emplace<M>();break;case 0x359c:j.emplace<G>();break;case 0x35bc:if(!nested)return false;j.emplace<G>(true);break;case 0x354e:if(!nested)return false;j.emplace<P>(uint8_t(c.reg8(13)));break;case 0x35fe:if(!nested)return false;j.emplace<S>(0x354c);break;case 0x368a:if(!nested)return false;j.emplace<A>();break;case 0x37ac:case 0x37b6:case 0x37c0:{if(!nested||!depth_)return false;const auto*parent=std::get_if<A>(&jobs_[depth_-1]);if(!parent||!parent->task().awaitingChild())return false;j.emplace<K>(uint32_t(c.getPC())==0x37ac?ArpSeekEmitTask::Kind::Up:uint32_t(c.getPC())==0x37b6?ArpSeekEmitTask::Kind::Down:ArpSeekEmitTask::Kind::ValueOnly,parent->task().returnAddress());break;}case 0x2c86:case 0x2cb8:if(!nested)return false;j.emplace<F>(uint32_t(c.getPC())==0x2c86?MidiSeekNoteTask::Kind::Upper:MidiSeekNoteTask::Kind::Lower,uint8_t(c.reg8(13)),uint32_t(c.reg32(3)));break;case 0x3660:if(!nested)return false;j.emplace<D>();break;case 0x255a:if(!nested)return false;j.emplace<O>(ArpMidiOutputTask::Kind::Off,0x35ee);break;case 0x2570:if(!nested)return false;j.emplace<O>(ArpMidiOutputTask::Kind::On,0x37fa);break;case 0x37ce:if(!nested)return false;j.emplace<E>(uint8_t(c.reg8(13)));break;case 0x20ce:if(!nested)return false;j.emplace<L>();break;case 0xb0c:if(!nested)return false;j.emplace<Q>(uint8_t(c.reg8(14)));break;case 0x2b7a:if(!nested)return false;j.emplace<C>();break;case 0x2c16:if(!nested)return false;j.emplace<H>(MidiPhysicalScanTask::Kind::Held);break;default:return false;}++depth_;return true;}
 std::array<Job,8>jobs_{};unsigned depth_=0;
};
}
